/*
 * Track runtime (word ABI).
 *
 * Every function exported to Track takes and returns 64-bit words (`tk_w`):
 * integers and booleans are plain values, strings are NUL-terminated
 * `char*` pointers, and handles (files, Vec, collections, builders) are
 * pointers to runtime-owned records. This single file is linked by both
 * compilers: the Rust bootstrap compiler embeds it with `include_str!`, and
 * the self-hosted compiler embeds a generated copy (`compiler/src/runtime_c.trk`,
 * regenerated by `scripts/embed_runtime.sh`).
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <ctype.h>
#include <stdint.h>
#include <errno.h>
#include <signal.h>

typedef int64_t tk_w;

#define TK_PTR(w) ((void *)(uintptr_t)(w))
#define TK_STR(w) ((const char *)(uintptr_t)(w))
#define TK_WORD(p) ((tk_w)(uintptr_t)(p))

/* ---------------------------------------------------------------- process */

static int g_argc = 0;
static char **g_argv = NULL;

/* Called from the generated `main` entry point before any Track code runs. */
tk_w track_runtime_init(tk_w argc, tk_w argv) {
    g_argc = (int)argc;
    g_argv = (char **)TK_PTR(argv);
    return 0;
}

tk_w os_args_count(void) { return g_argc; }

static char *tk_dup_n(const char *s, size_t n) {
    char *out = (char *)malloc(n + 1);
    if (!out) {
        fprintf(stderr, "\nTrack Runtime Error: Out of memory allocation failure!\n");
        exit(137);
    }
    if (n > 0) memcpy(out, s, n);
    out[n] = '\0';
    return out;
}

static char *tk_dup(const char *s) { return tk_dup_n(s ? s : "", s ? strlen(s) : 0); }

tk_w os_arg(tk_w idx) {
    if (g_argv && idx >= 0 && idx < g_argc) return TK_WORD(tk_dup(g_argv[idx]));
    return TK_WORD(tk_dup(""));
}

tk_w sys_exit(tk_w code) {
    fflush(stdout);
    exit((int)code);
    return 0;
}

static int is_valid_string_pointer(const void *ptr) {
    if (!ptr || (uintptr_t)ptr < 0x10000) return 0;
    int pfd[2];
    if (pipe(pfd) < 0) return 0;
    ssize_t res = write(pfd[1], ptr, 1);
    close(pfd[0]);
    close(pfd[1]);
    return res == 1;
}

/* Fatal abort: print message and terminate the process. No unwinding —
 * stack frames are simply discarded (linear cleanup is skipped by design). */
tk_w track_abort(tk_w msg) {
    const char *s = TK_STR(msg);
    fflush(stdout);
    if (s && is_valid_string_pointer(s)) {
        fprintf(stderr, "Track abort: %s\n", s);
    } else {
        fprintf(stderr, "Track abort\n");
    }
    fflush(stderr);
    exit(134);
    return 0;
}

/* Integer division by zero or INT64_MIN / -1: trap like a hardware divide
 * fault (SIGFPE) without flushing buffered output. */
tk_w track_trap_div(void) {
    raise(SIGFPE);
    abort();
    return 0;
}

tk_w sys_exec(tk_w cmd) {
    if (!cmd) return -1;
    fflush(stdout);
    fflush(stderr);
    int status = system(TK_STR(cmd));
    if (status == -1) return -1;
    if (WIFEXITED(status)) return WEXITSTATUS(status);
    return 128 + (WIFSIGNALED(status) ? WTERMSIG(status) : 0);
}

tk_w process_spawn(tk_w cmd) { return sys_exec(cmd); }

tk_w clock_ms(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (tk_w)ts.tv_sec * 1000 + (tk_w)ts.tv_nsec / 1000000;
}

tk_w env_get(tk_w key) {
    const char *val = key ? getenv(TK_STR(key)) : NULL;
    return TK_WORD(tk_dup(val ? val : ""));
}

tk_w env_exists(tk_w key) { return key && getenv(TK_STR(key)) ? 1 : 0; }

/* ----------------------------------------------------------------- memory */

static size_t g_allocated_bytes = 0;
static size_t g_max_memory_limit = 536870912; /* 512MB default memory boundary limit */

tk_w sys_set_memory_limit(tk_w bytes) {
    if (bytes > 0) g_max_memory_limit = (size_t)bytes;
    return 0;
}

tk_w sys_get_memory_used(void) { return (tk_w)g_allocated_bytes; }

tk_w alloc(tk_w size_w) {
    size_t size = (size_t)size_w;
    if (size_w <= 0) return 0;
    if (g_allocated_bytes + size > g_max_memory_limit) {
        fprintf(stderr, "\nTrack Runtime Error: Process memory boundary limit exceeded! (Allocated: %zu bytes, Requested: %zu bytes, Limit: %zu bytes)\n", g_allocated_bytes, size, g_max_memory_limit);
        fflush(stderr);
        exit(137);
    }
    size_t *ptr = (size_t *)calloc(1, size + sizeof(size_t));
    if (!ptr) {
        fprintf(stderr, "\nTrack Runtime Error: Out of memory allocation failure!\n");
        fflush(stderr);
        exit(137);
    }
    *ptr = size;
    g_allocated_bytes += size;
    return TK_WORD(ptr + 1);
}

tk_w dealloc(tk_w p) {
    if (!p) return 0;
    size_t *raw = (size_t *)TK_PTR(p) - 1;
    size_t size = *raw;
    g_allocated_bytes = g_allocated_bytes >= size ? g_allocated_bytes - size : 0;
    free(raw);
    return 0;
}

tk_w mem_realloc(tk_w p, tk_w new_size_w) {
    if (!p) return alloc(new_size_w);
    if (new_size_w <= 0) return dealloc(p);
    size_t new_size = (size_t)new_size_w;
    size_t *raw = (size_t *)TK_PTR(p) - 1;
    size_t old_size = *raw;
    if (g_allocated_bytes - old_size + new_size > g_max_memory_limit) {
        fprintf(stderr, "\nTrack Runtime Error: Process memory boundary limit exceeded! (Allocated: %zu bytes, Requested: %zu bytes, Limit: %zu bytes)\n", g_allocated_bytes, new_size, g_max_memory_limit);
        fflush(stderr);
        exit(137);
    }
    size_t *new_raw = (size_t *)realloc(raw, new_size + sizeof(size_t));
    if (!new_raw) {
        fprintf(stderr, "\nTrack Runtime Error: Out of memory reallocation failure!\n");
        fflush(stderr);
        exit(137);
    }
    *new_raw = new_size;
    g_allocated_bytes = g_allocated_bytes - old_size + new_size;
    return TK_WORD(new_raw + 1);
}

/* Copy `count` words to a fresh heap cell (escaping tuples). */
tk_w track_words_copy(tk_w src, tk_w count) {
    tk_w dst = alloc(count > 0 ? count * 8 : 8);
    if (src && count > 0) memcpy(TK_PTR(dst), TK_PTR(src), (size_t)count * 8);
    return dst;
}

/* ------------------------------------------------------------------ print */

tk_w print(tk_w val) {
    if (val >= 0x10000 && is_valid_string_pointer(TK_PTR(val))) {
        const char *str = TK_STR(val);
        int is_str = 1;
        int len = 0;
        while (len < 4096) {
            unsigned char c = (unsigned char)str[len];
            if (c == 0) break;
            if (c < 9 || (c > 13 && c < 32) || c > 126) {
                is_str = 0;
                break;
            }
            len++;
        }
        if (is_str && len > 0) {
            printf("%s\n", str);
            return 0;
        }
    }
    printf("%lld\n", (long long)val);
    return 0;
}

tk_w println(tk_w val) { return print(val); }
tk_w print_int(tk_w val) { printf("%lld\n", (long long)val); return 0; }
tk_w print_hex(tk_w val) { printf("0x%llx\n", (unsigned long long)val); return 0; }
tk_w print_str(tk_w s) { printf("%s\n", s ? TK_STR(s) : ""); return 0; }

tk_w print_err(tk_w s) {
    if (s) {
        fflush(stdout);
        fprintf(stderr, "%s\n", TK_STR(s));
        fflush(stderr);
    }
    return 0;
}

tk_w eprint(tk_w s) { return print_err(s); }

/* Unformatted output (no trailing newline, no int/string guessing). */
tk_w track_out(tk_w s) {
    if (s) fputs(TK_STR(s), stdout);
    return 0;
}

tk_w track_err(tk_w s) {
    if (s) {
        fflush(stdout);
        fputs(TK_STR(s), stderr);
        fflush(stderr);
    }
    return 0;
}

tk_w read_line(void) {
    size_t cap = 128, len = 0;
    char *buf = (char *)malloc(cap);
    int c;
    while (buf && (c = fgetc(stdin)) != EOF && c != '\n') {
        if (len + 1 >= cap) buf = (char *)realloc(buf, cap *= 2);
        if (buf) buf[len++] = (char)c;
    }
    if (!buf) return TK_WORD(tk_dup(""));
    buf[len] = '\0';
    return TK_WORD(buf);
}

/* ---------------------------------------------------------------- strings */

tk_w str_from_literal(tk_w raw) { return TK_WORD(tk_dup(TK_STR(raw))); }

tk_w str_free(tk_w s) {
    (void)s; /* literals and runtime strings share a representation; never freed */
    return 0;
}

tk_w str_len(tk_w s) { return s ? (tk_w)strlen(TK_STR(s)) : 0; }

tk_w str_eq(tk_w a, tk_w b) {
    if (!a || !b) return a == b ? 1 : 0;
    return strcmp(TK_STR(a), TK_STR(b)) == 0 ? 1 : 0;
}

tk_w str_concat(tk_w a, tk_w b) {
    size_t a_len = a ? strlen(TK_STR(a)) : 0;
    size_t b_len = b ? strlen(TK_STR(b)) : 0;
    char *out = tk_dup_n("", 0);
    out = (char *)realloc(out, a_len + b_len + 1);
    if (!out) exit(137);
    if (a_len) memcpy(out, TK_STR(a), a_len);
    if (b_len) memcpy(out + a_len, TK_STR(b), b_len);
    out[a_len + b_len] = '\0';
    return TK_WORD(out);
}

tk_w str_find(tk_w s, tk_w sub) {
    if (!s || !sub) return -1;
    const char *p = strstr(TK_STR(s), TK_STR(sub));
    return p ? (tk_w)(p - TK_STR(s)) : -1;
}

tk_w str_contains(tk_w s, tk_w sub) {
    if (!s || !sub) return 0;
    return strstr(TK_STR(s), TK_STR(sub)) ? 1 : 0;
}

tk_w str_to_int(tk_w s) { return s ? atoll(TK_STR(s)) : 0; }

/* Predicate companion for str_to_int: distinguishes a genuine "0" from a parse failure. */
tk_w str_is_int(tk_w s_w) {
    const char *s = TK_STR(s_w);
    if (!s || *s == '\0') return 0;
    const char *p = s;
    if (*p == '+' || *p == '-') p++;
    if (*p == '\0') return 0;
    for (; *p; p++) {
        if (!isdigit((unsigned char)*p)) return 0;
    }
    return 1;
}

tk_w int_to_str(tk_w val) {
    char buf[32];
    snprintf(buf, sizeof(buf), "%lld", (long long)val);
    return TK_WORD(tk_dup(buf));
}

tk_w str_starts_with(tk_w s, tk_w prefix) {
    if (!s || !prefix) return 0;
    size_t lp = strlen(TK_STR(prefix));
    return strncmp(TK_STR(s), TK_STR(prefix), lp) == 0 ? 1 : 0;
}

tk_w str_ends_with(tk_w s, tk_w suffix) {
    if (!s || !suffix) return 0;
    size_t ls = strlen(TK_STR(s));
    size_t lp = strlen(TK_STR(suffix));
    if (lp > ls) return 0;
    return strcmp(TK_STR(s) + ls - lp, TK_STR(suffix)) == 0 ? 1 : 0;
}

tk_w str_substr(tk_w s_w, tk_w start, tk_w len) {
    const char *s = TK_STR(s_w);
    if (!s || start < 0 || len <= 0) return TK_WORD(tk_dup(""));
    /* Bounded scan: never walk past the requested window of a long source. */
    size_t avail = strnlen(s, (size_t)start + (size_t)len);
    if ((size_t)start >= avail) return TK_WORD(tk_dup(""));
    return TK_WORD(tk_dup_n(s + start, avail - (size_t)start));
}

tk_w str_trim(tk_w s_w) {
    const char *s = TK_STR(s_w);
    if (!s) return TK_WORD(tk_dup(""));
    while (*s && isspace((unsigned char)*s)) s++;
    size_t len = strlen(s);
    while (len > 0 && isspace((unsigned char)s[len - 1])) len--;
    return TK_WORD(tk_dup_n(s, len));
}

tk_w str_char_at(tk_w s_w, tk_w idx) {
    const char *s = TK_STR(s_w);
    if (!s || idx < 0) return 0;
    size_t len = strnlen(s, (size_t)idx + 1);
    if ((size_t)idx >= len) return 0;
    return (unsigned char)s[idx];
}

/* Copy a string's bytes into a collection for O(1) bounds-checked access. */
tk_w track_i64_collection_new(tk_w requested_cap);
tk_w track_i64_collection_push(tk_w handle, tk_w value);

tk_w track_str_bytes(tk_w s_w) {
    const unsigned char *s = (const unsigned char *)TK_STR(s_w);
    size_t len = s ? strlen((const char *)s) : 0;
    tk_w out = track_i64_collection_new((tk_w)len + 1);
    for (size_t i = 0; i < len; i++) track_i64_collection_push(out, s[i]);
    return out;
}

tk_w char_is_digit(tk_w c) { return c >= 0 && c < 256 && isdigit((int)c) ? 1 : 0; }
tk_w char_is_alpha(tk_w c) { return c >= 0 && c < 256 && isalpha((int)c) ? 1 : 0; }
tk_w char_is_alphanumeric(tk_w c) { return c >= 0 && c < 256 && isalnum((int)c) ? 1 : 0; }
tk_w char_is_space(tk_w c) { return c >= 0 && c < 256 && isspace((int)c) ? 1 : 0; }
tk_w char_to_upper(tk_w c) { return c >= 0 && c < 256 ? (unsigned char)toupper((int)c) : c; }
tk_w char_to_lower(tk_w c) { return c >= 0 && c < 256 ? (unsigned char)tolower((int)c) : c; }

/* ------------------------------------------------------------------ paths */

tk_w path_basename(tk_w path_w) {
    const char *path = TK_STR(path_w);
    if (!path) return TK_WORD(tk_dup(""));
    const char *slash = strrchr(path, '/');
    return TK_WORD(tk_dup(slash ? slash + 1 : path));
}

tk_w path_ext(tk_w path_w) {
    const char *path = TK_STR(path_w);
    if (!path) return TK_WORD(tk_dup(""));
    const char *dot = strrchr(path, '.');
    if (!dot || dot == path) return TK_WORD(tk_dup(""));
    return TK_WORD(tk_dup(dot + 1));
}

tk_w path_join(tk_w a_w, tk_w b_w) {
    const char *a = a_w ? TK_STR(a_w) : "";
    const char *b = b_w ? TK_STR(b_w) : "";
    size_t la = strlen(a), lb = strlen(b);
    int slash = la > 0 && a[la - 1] != '/' && (lb == 0 || b[0] != '/');
    char *out = tk_dup_n(a, la);
    out = (char *)realloc(out, la + (size_t)slash + lb + 1);
    if (!out) exit(137);
    if (slash) out[la] = '/';
    memcpy(out + la + slash, b, lb + 1);
    return TK_WORD(out);
}

/* ------------------------------------------------------------------ files */

tk_w file_open(tk_w path, tk_w mode) {
    if (!path || !mode) return 0;
    return TK_WORD(fopen(TK_STR(path), TK_STR(mode)));
}

tk_w file_close(tk_w f) {
    if (f) fclose((FILE *)TK_PTR(f));
    return 0;
}

tk_w file_read_all(tk_w handle) {
    FILE *f = (FILE *)TK_PTR(handle);
    if (!f || fseek(f, 0, SEEK_END) != 0) return TK_WORD(tk_dup(""));
    long end = ftell(f);
    if (end < 0 || fseek(f, 0, SEEK_SET) != 0) return TK_WORD(tk_dup(""));
    char *buf = (char *)malloc((size_t)end + 1);
    if (!buf) exit(137);
    size_t got = fread(buf, 1, (size_t)end, f);
    buf[got] = '\0';
    return TK_WORD(buf);
}

tk_w file_write(tk_w handle, tk_w content) {
    FILE *f = (FILE *)TK_PTR(handle);
    if (!f || !content) return -1;
    size_t len = strlen(TK_STR(content));
    return fwrite(TK_STR(content), 1, len, f) == len ? 0 : -1;
}

tk_w file_exists(tk_w path) { return path && access(TK_STR(path), F_OK) == 0 ? 1 : 0; }

tk_w file_remove(tk_w path) { return path && unlink(TK_STR(path)) == 0 ? 0 : -1; }

tk_w file_size(tk_w path) {
    struct stat st;
    if (!path || stat(TK_STR(path), &st) != 0) return -1;
    return (tk_w)st.st_size;
}

tk_w dir_exists(tk_w path) {
    struct stat st;
    return path && stat(TK_STR(path), &st) == 0 && S_ISDIR(st.st_mode) ? 1 : 0;
}

tk_w file_copy(tk_w src, tk_w dst) {
    if (!src || !dst) return -1;
    FILE *in = fopen(TK_STR(src), "rb");
    if (!in) return -1;
    FILE *out = fopen(TK_STR(dst), "wb");
    if (!out) {
        fclose(in);
        return -1;
    }
    char buf[4096];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), in)) > 0) fwrite(buf, 1, n, out);
    fclose(in);
    fclose(out);
    return 0;
}

/* Whole-file helpers: open, transfer, and close in one call. */
tk_w track_file_read(tk_w path) {
    FILE *f = path ? fopen(TK_STR(path), "rb") : NULL;
    if (!f) return TK_WORD(tk_dup(""));
    tk_w out = file_read_all(TK_WORD(f));
    fclose(f);
    return out;
}

tk_w track_file_write_all(tk_w path, tk_w content) {
    FILE *f = path ? fopen(TK_STR(path), "wb") : NULL;
    if (!f) return -1;
    tk_w status = file_write(TK_WORD(f), content);
    if (fclose(f) != 0) status = -1;
    return status;
}

/* ------------------------------------------------------------------- math */

tk_w math_abs(tk_w x) { return x < 0 ? -x : x; }
tk_w math_min(tk_w a, tk_w b) { return a < b ? a : b; }
tk_w math_max(tk_w a, tk_w b) { return a > b ? a : b; }
tk_w math_clamp(tk_w v, tk_w lo, tk_w hi) { return v < lo ? lo : (v > hi ? hi : v); }
tk_w math_floor(tk_w x) { return x; }
tk_w math_ceil(tk_w x) { return x; }
tk_w math_round(tk_w x) { return x; }

tk_w math_pow(tk_w base, tk_w exp) {
    tk_w result = 1;
    if (exp < 0) return 0;
    while (exp > 0) {
        if (exp & 1) result = (tk_w)((uint64_t)result * (uint64_t)base);
        base = (tk_w)((uint64_t)base * (uint64_t)base);
        exp >>= 1;
    }
    return result;
}

tk_w math_sqrt(tk_w x) {
    if (x <= 0) return 0;
    uint64_t lo = 0, hi = 3037000499ULL; /* floor(sqrt(INT64_MAX)) */
    while (lo < hi) {
        uint64_t mid = (lo + hi + 1) / 2;
        if (mid * mid <= (uint64_t)x) lo = mid; else hi = mid - 1;
    }
    return (tk_w)lo;
}

static uint64_t g_rng_state = 0x853c49e65d8dbb29ULL;
tk_w math_random(void) {
    uint64_t x = g_rng_state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    g_rng_state = x;
    return (tk_w)x;
}

tk_w add(tk_w a, tk_w b) { return a + b; }
tk_w sum(tk_w a, tk_w b) { return a + b; }
tk_w sub(tk_w a, tk_w b) { return a - b; }

/* -------------------------------------------------------------------- Vec */

typedef struct {
    tk_w *data;
    tk_w len;
    tk_w cap;
} TrackVec;

tk_w vec_init(tk_w cap) {
    TrackVec *v = (TrackVec *)TK_PTR(alloc(sizeof(TrackVec)));
    v->cap = cap > 0 ? cap : 16;
    v->data = (tk_w *)TK_PTR(alloc(v->cap * (tk_w)sizeof(tk_w)));
    v->len = 0;
    return TK_WORD(v);
}

tk_w vec_push(tk_w h, tk_w val) {
    TrackVec *v = (TrackVec *)TK_PTR(h);
    if (!v) return 0;
    if (v->len == v->cap) {
        v->cap *= 2;
        v->data = (tk_w *)TK_PTR(mem_realloc(TK_WORD(v->data), v->cap * (tk_w)sizeof(tk_w)));
    }
    v->data[v->len++] = val;
    return 0;
}

tk_w vec_get(tk_w h, tk_w idx) {
    TrackVec *v = (TrackVec *)TK_PTR(h);
    return v && idx >= 0 && idx < v->len ? v->data[idx] : 0;
}

tk_w vec_set(tk_w h, tk_w idx, tk_w val) {
    TrackVec *v = (TrackVec *)TK_PTR(h);
    if (v && idx >= 0 && idx < v->len) v->data[idx] = val;
    return 0;
}

tk_w vec_pop(tk_w h) {
    TrackVec *v = (TrackVec *)TK_PTR(h);
    return v && v->len > 0 ? v->data[--v->len] : 0;
}

tk_w vec_len(tk_w h) {
    TrackVec *v = (TrackVec *)TK_PTR(h);
    return v ? v->len : 0;
}

tk_w vec_clear(tk_w h) {
    TrackVec *v = (TrackVec *)TK_PTR(h);
    if (v) v->len = 0;
    return 0;
}

tk_w vec_reserve(tk_w h, tk_w cap) {
    TrackVec *v = (TrackVec *)TK_PTR(h);
    if (v && cap > v->cap) {
        v->data = (tk_w *)TK_PTR(mem_realloc(TK_WORD(v->data), cap * (tk_w)sizeof(tk_w)));
        v->cap = cap;
    }
    return 0;
}

tk_w vec_free(tk_w h) {
    TrackVec *v = (TrackVec *)TK_PTR(h);
    if (v) {
        dealloc(TK_WORD(v->data));
        dealloc(h);
    }
    return 0;
}

/* --------------------------------------------- opaque 64-bit collections */

/* Growable word vectors used by the self-hosted compiler. Track only carries
 * the stable pointer handle; layout and capacity stay in the runtime. */
typedef struct {
    tk_w *data;
    tk_w len;
    tk_w cap;
} TrackI64Collection;

tk_w track_i64_collection_new(tk_w requested_cap) {
    tk_w cap = requested_cap > 0 ? requested_cap : 16;
    TrackI64Collection *c = (TrackI64Collection *)malloc(sizeof(TrackI64Collection));
    if (!c) exit(137);
    c->data = (tk_w *)malloc((size_t)cap * sizeof(tk_w));
    if (!c->data) exit(137);
    c->len = 0;
    c->cap = cap;
    return TK_WORD(c);
}

tk_w track_i64_collection_len(tk_w h) {
    const TrackI64Collection *c = (const TrackI64Collection *)TK_PTR(h);
    return c ? c->len : 0;
}

tk_w track_i64_collection_push(tk_w h, tk_w value) {
    TrackI64Collection *c = (TrackI64Collection *)TK_PTR(h);
    if (!c) return -1;
    if (c->len == c->cap) {
        c->cap *= 2;
        c->data = (tk_w *)realloc(c->data, (size_t)c->cap * sizeof(tk_w));
        if (!c->data) exit(137);
    }
    c->data[c->len] = value;
    return c->len++;
}

tk_w track_i64_collection_get(tk_w h, tk_w index) {
    const TrackI64Collection *c = (const TrackI64Collection *)TK_PTR(h);
    if (!c || index < 0 || index >= c->len) return 0;
    return c->data[index];
}

tk_w track_i64_collection_set(tk_w h, tk_w index, tk_w value) {
    TrackI64Collection *c = (TrackI64Collection *)TK_PTR(h);
    if (!c || index < 0 || index >= c->len) return 0;
    c->data[index] = value;
    return 1;
}

tk_w track_i64_collection_pop(tk_w h) {
    TrackI64Collection *c = (TrackI64Collection *)TK_PTR(h);
    if (!c || c->len == 0) return 0;
    return c->data[--c->len];
}

/* Shrink to `len` elements (no-op when already shorter). */
tk_w track_i64_collection_truncate(tk_w h, tk_w len) {
    TrackI64Collection *c = (TrackI64Collection *)TK_PTR(h);
    if (c && len >= 0 && len < c->len) c->len = len;
    return 0;
}

/* --------------------------------------------------------- string builder */

typedef struct {
    char *data;
    size_t len;
    size_t cap;
} TrackStrBuf;

static void sb_reserve(TrackStrBuf *b, size_t extra) {
    if (b->len + extra + 1 <= b->cap) return;
    while (b->len + extra + 1 > b->cap) b->cap *= 2;
    b->data = (char *)realloc(b->data, b->cap);
    if (!b->data) exit(137);
}

tk_w track_sb_new(void) {
    TrackStrBuf *b = (TrackStrBuf *)malloc(sizeof(TrackStrBuf));
    if (!b) exit(137);
    b->cap = 256;
    b->len = 0;
    b->data = (char *)malloc(b->cap);
    if (!b->data) exit(137);
    b->data[0] = '\0';
    return TK_WORD(b);
}

tk_w track_sb_push(tk_w h, tk_w s) {
    TrackStrBuf *b = (TrackStrBuf *)TK_PTR(h);
    if (!b || !s) return 0;
    size_t n = strlen(TK_STR(s));
    sb_reserve(b, n);
    memcpy(b->data + b->len, TK_STR(s), n + 1);
    b->len += n;
    return 0;
}

tk_w track_sb_push_byte(tk_w h, tk_w byte) {
    TrackStrBuf *b = (TrackStrBuf *)TK_PTR(h);
    if (!b) return 0;
    sb_reserve(b, 1);
    b->data[b->len++] = (char)byte;
    b->data[b->len] = '\0';
    return 0;
}

tk_w track_sb_push_int(tk_w h, tk_w val) {
    char buf[32];
    snprintf(buf, sizeof(buf), "%lld", (long long)val);
    return track_sb_push(h, TK_WORD(buf));
}

tk_w track_sb_len(tk_w h) {
    TrackStrBuf *b = (TrackStrBuf *)TK_PTR(h);
    return b ? (tk_w)b->len : 0;
}

/* Copy the builder contents into a new string. */
tk_w track_sb_str(tk_w h) {
    TrackStrBuf *b = (TrackStrBuf *)TK_PTR(h);
    return TK_WORD(b ? tk_dup_n(b->data, b->len) : tk_dup(""));
}

tk_w track_sb_clear(tk_w h) {
    TrackStrBuf *b = (TrackStrBuf *)TK_PTR(h);
    if (b) {
        b->len = 0;
        b->data[0] = '\0';
    }
    return 0;
}

/* ---------------------------------------------------------------- network */

tk_w net_socket_tcp_listen(tk_w port) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) return -1;
    int opt = 1;
    setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons((uint16_t)port);
    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        if (errno == EADDRINUSE) {
            fprintf(stderr, "Track Network Error: Port conflict! Port %d is already in use by another process.\n", (int)port);
        } else {
            fprintf(stderr, "Track Network Error: Failed to bind TCP socket on port %d (errno: %d).\n", (int)port, errno);
        }
        fflush(stderr);
        close(fd);
        return -1;
    }
    if (listen(fd, 128) < 0) {
        close(fd);
        return -1;
    }
    return fd;
}

tk_w net_socket_accept(tk_w server_fd) {
    if (server_fd < 0) return -1;
    struct sockaddr_in client_addr;
    socklen_t addrlen = sizeof(client_addr);
    return accept((int)server_fd, (struct sockaddr *)&client_addr, &addrlen);
}

tk_w net_socket_connect(tk_w host, tk_w port) {
    if (!host) return -1;
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) return -1;
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons((uint16_t)port);
    if (inet_pton(AF_INET, TK_STR(host), &addr.sin_addr) <= 0 ||
        connect(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        close(fd);
        return -1;
    }
    return fd;
}

tk_w net_socket_send(tk_w fd, tk_w data, tk_w len) {
    if (fd < 0 || !data) return -1;
    return (tk_w)send((int)fd, TK_PTR(data), (size_t)len, 0);
}

tk_w net_socket_recv(tk_w fd, tk_w buf, tk_w max_len) {
    if (fd < 0 || !buf) return -1;
    return (tk_w)recv((int)fd, TK_PTR(buf), (size_t)max_len, 0);
}

tk_w net_socket_close(tk_w fd) {
    if (fd >= 0) close((int)fd);
    return 0;
}
